   const rows=[],ids=new Set();let offset=0;do{const result=await call('templates',{acao:'listar',marca:captured.brand,canal:'email',offset:String(offset),limit:'20'});if(scope!==captured||campaign?.id!==id||campaign?.version!==version||revision!==rev||result.contract!=='crm-template-read-v1'||result.brand!==captured.brand||!Array.isArray(result.templates)||result.offset!==offset||!Number.isSafeInteger(result.total)||result.total>1000)throw Error('MODEL_SCOPE_CHANGED');for(const model of result.templates){if(model.brand!==captured.brand||ids.has(model.id))throw Error('MODEL_SCOPE_CHANGED');ids.add(model.id);rows.push(model);}if(result.next_offset!==null&&(!Number.isSafeInteger(result.next_offset)||result.next_offset!==offset+20))throw Error('MODEL_PAGE_CHANGED');offset=result.next_offset;}while(offset!==null);
