    node.querySelector('[data-rule-value]').innerHTML='<label class="form-label">'+(type==='days'?'Dias':type==='money'?'Valor ('+esc(catalog.currency||'moeda não confirmada')+')':'Valor')+(choices?'<select class="form-select" data-value>'+choices.map(c=>'<option value="'+esc(c.value)+'"'+(c.available?'':' disabled')+'>'+esc(c.name)+'</option>').join('')+'</select>':'<input class="form-control" data-value required type="'+(type==='date'?'date':['integer','days'].includes(type)?'number':'text')+'"'+(['integer','days'].includes(type)?' min="'+(type==='days'?1:0)+'" step="1"':'')+'>')+'</label>';if(value!==undefined)node.querySelector('[data-value]').value=value;
    const confirm=node.querySelector('[data-confirm-label]');confirm.classList.toggle('d-none',!key.startsWith('purchase.'));if(!key.startsWith('purchase.'))node.querySelector('[data-rule-confirm]').checked=false;
